/** @jest-environment jsdom */
import { act, cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import VocabularyPage from '../../client/src/pages/VocabularyPage';
import VocabularyReview from '../../client/src/features/vocabulary/VocabularyReview';
import { api, type SavedVocabularyWord } from '../../client/src/lib/api';

jest.mock('../../client/src/contexts/AuthContext', () => ({ useAuth: () => ({ user: { id: 'learner' }, loading: false }) }));
jest.mock('../../client/src/lib/speech', () => ({ speakEnglishText: jest.fn() }));
jest.mock('../../client/src/lib/api', () => ({ api: { getSavedVocabulary: jest.fn(), getSavedVocabularySession: jest.fn(), reviewSavedVocabulary: jest.fn(), removeSavedVocabulary: jest.fn(), replaySavedVocabulary: jest.fn() } }));
const word: SavedVocabularyWord = {
  id: 'saved-1', word: 'consistent', meaning: 'đều đặn', phonetic: '/kənˈsɪstənt/', partOfSpeech: 'Tính từ', definition: null,
  status: 'MASTERED', reviewCount: 4, correctCount: 4, streak: 4, lapses: 0, intervalDays: 18, easeFactor: 2.5,
  nextReviewAt: '2099-01-01T00:00:00Z', lastReviewedAt: null, createdAt: '2026-10-25T00:00:00Z',
  sources: [{ id: 'source-1', sourceType: 'lesson', sourceId: 'lesson-01', title: 'Small habits', sentence: 'Small consistent actions matter.', sentenceTranslation: 'Hành động đều đặn rất quan trọng.', startTime: 2, endTime: 5 }],
};
beforeEach(() => {
  jest.clearAllMocks();
  window.scrollTo = jest.fn();
  HTMLDialogElement.prototype.showModal = function () { this.open = true; };
  HTMLDialogElement.prototype.close = function () { this.open = false; };
  jest.mocked(api.getSavedVocabulary).mockResolvedValue({ words: [word], stats: { total: 1, due: 0, mastered: 1 }, sources: [{ key: 'lesson:lesson-01', title: 'Small habits' }] });
  jest.mocked(api.getSavedVocabularySession).mockResolvedValue({ words: [word] });
  jest.mocked(api.reviewSavedVocabulary).mockResolvedValue(word);
});
afterEach(cleanup);

it('starts a manual mastered session and keeps global review independent of filters', async () => {
  render(<MemoryRouter><VocabularyPage /></MemoryRouter>);
  await screen.findByRole('button', { name: 'Chi tiết từ consistent' });
  fireEvent.click(screen.getByRole('button', { name: 'Đã nhớ 1' }));
  await waitFor(() => expect(jest.mocked(api.getSavedVocabulary).mock.calls.at(-1)![0]).toMatchObject({ status: 'mastered' }));
  await waitFor(() => expect((screen.getByRole('button', { name: 'Ôn lại', exact: true }) as HTMLButtonElement).disabled).toBe(false));
  fireEvent.click(screen.getByRole('button', { name: 'Ôn lại', exact: true }));
  await screen.findByText('Ôn chủ động · Đã nhớ');
  expect(api.getSavedVocabularySession).toHaveBeenLastCalledWith(expect.objectContaining({ status: 'mastered' }));
  fireEvent.click(screen.getByRole('button', { name: 'Kết thúc lượt ôn' }));
  await waitFor(() => expect((screen.getByRole('button', { name: 'Ôn tất cả · 1 từ' }) as HTMLButtonElement).disabled).toBe(false));
  fireEvent.click(screen.getByRole('button', { name: 'Ôn tất cả · 1 từ' }));
  await screen.findByText('Ôn chủ động · Tất cả');
  expect(api.getSavedVocabularySession).toHaveBeenLastCalledWith({ status: 'all' });
});

it('hides the answer until requested and records an actual self-assessment', async () => {
  render(<VocabularyReview words={[word]} label="Ôn chủ động · Đã nhớ" onClose={jest.fn()} onReplay={jest.fn()} />);
  expect(screen.queryByText('đều đặn')).toBeNull();
  expect(screen.queryByRole('button', { name: 'Chưa nhớ' })).toBeNull();
  fireEvent.click(screen.getByRole('button', { name: 'Xem đáp án' }));
  expect(screen.getByText('đều đặn')).toBeTruthy();
  fireEvent.click(screen.getByRole('button', { name: 'Chưa nhớ' }));
  await screen.findByRole('heading', { name: 'Đã hoàn thành lượt ôn' });
  expect(api.reviewSavedVocabulary).toHaveBeenCalledWith(word.id, expect.objectContaining({ correct: false, expectedReviewCount: 4, requestId: expect.any(String) }));
});

it('keeps a failed answer on screen and retries it with the same idempotency key', async () => {
  jest.mocked(api.reviewSavedVocabulary).mockRejectedValueOnce(new Error('Mất kết nối'));
  render(<VocabularyReview words={[word]} label="Ôn chủ động · Đã nhớ" onClose={jest.fn()} onReplay={jest.fn()} />);
  fireEvent.click(screen.getByRole('button', { name: 'Xem đáp án' }));
  fireEvent.click(screen.getByRole('button', { name: 'Đã nhớ', exact: true }));
  await screen.findByRole('button', { name: 'Thử lưu lại' });
  expect(screen.queryByRole('heading', { name: 'Đã hoàn thành lượt ôn' })).toBeNull();
  const firstRequest = jest.mocked(api.reviewSavedVocabulary).mock.calls[0][1];
  await act(async () => fireEvent.click(screen.getByRole('button', { name: 'Thử lưu lại' })));
  expect(jest.mocked(api.reviewSavedVocabulary).mock.calls[1][1]).toEqual(firstRequest);
  expect(screen.getByRole('heading', { name: 'Đã hoàn thành lượt ôn' })).toBeTruthy();
});

it('offers review for a mastered word from its detail sheet', async () => {
  render(<MemoryRouter><VocabularyPage /></MemoryRouter>);
  fireEvent.click(await screen.findByRole('button', { name: 'Chi tiết từ consistent' }));
  expect(screen.getByRole('dialog')).toBeTruthy();
  fireEvent.click(screen.getByRole('button', { name: 'Ôn lại từ này' }));
  await screen.findByText('Ôn chủ động · Một từ');
  expect(api.getSavedVocabularySession).toHaveBeenLastCalledWith({ wordId: word.id });
});
